// Get current time in milliseconds (13 digits)
const ts_ms = Date.now();

// Convert to nanoseconds (19 digits) by appending zeros as a string
// This avoids JavaScript math precision loss
const ts_nanoseconds = ts_ms.toString() + "000000";

// Convert to integer (BigInt is not needed, JS will parse this fine up to 19 digits for string formatting)
const ts_int = parseInt(ts_nanoseconds);

// Generate realistic random values for Indonesian green infrastructure
const temperature = (Math.random() * 9.5 + 26.0).toFixed(2); // 26.0 to 35.5 °C
const humidity = (Math.random() * 35.0 + 60.0).toFixed(2);   // 60.0 to 95.0 %
const soil_humidity = (Math.random() * 40.0 + 30.0).toFixed(2); // 30.0 to 70.0 %
const pm25 = (Math.random() * 50.0 + 15.0).toFixed(2);       // 15.0 to 65.0 ug/m3

msg.payload = {
    "ts": ts_int,
    "loc_id": "JKT-NodeRED",
    "readings": [
        {
            "sensor_id": "S-TEMP-01",
            "type": "temperature",
            "unit": "C",
            "val": parseFloat(temperature)
        },
        {
            "sensor_id": "S-HUM-01",
            "type": "humidity",
            "unit": "%",
            "val": parseFloat(humidity)
        },
        {
            "sensor_id": "S-SOIL-01",
            "type": "soil_humidity",
            "unit": "%",
            "val": parseFloat(soil_humidity)
        },
        {
            "sensor_id": "S-PM25-01",
            "type": "pm25",
            "unit": "ug/m3",
            "val": parseFloat(pm25)
        }
    ]
};

return msg;

const query = `
SELECT
    max(timestamp) AS timestamp,
    max(CASE WHEN sensor_type='temperature' THEN value END) AS temperature,
    max(CASE WHEN sensor_type='humidity' THEN value END) AS humidity,
    max(CASE WHEN sensor_type='soil_humidity' THEN value END) AS soil_humidity,
    max(CASE WHEN sensor_type='pm25' THEN value END) AS pm25,
    max(ikl) AS ikl,
    max(ikl_label) AS ikl_label
FROM (
    SELECT *
    FROM sensor_readings
    LATEST ON timestamp PARTITION BY sensor_type
)
`;

msg.method = "GET";

// Untuk sementara gunakan IP server
msg.url = "http://questdb:9000/exec?query=" + encodeURIComponent(query);

return msg;

const row = msg.payload.dataset[0];

msg.payload = {
    timestamp: row[0],
    temperature: row[1],
    humidity: row[2],
    soil_humidity: row[3],
    pm25: row[4],
    ikl: row[5],
    ikl_label: row[6]
};

msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET",
    "Access-Control-Allow-Headers": "Content-Type"
};

return msg;

const rows = msg.payload.dataset || [];

msg.payload = rows.map(row => ({
    timestamp: row[0],
    value: row[1]
}));

msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET",
    "Access-Control-Allow-Headers": "Content-Type"
};

return msg;

const sensor = msg.req.query.sensor || "temperature";

const query = `
SELECT
    timestamp,
    avg(value) AS value
FROM sensor_readings
WHERE sensor_type='${sensor}'
AND timestamp >= dateadd('h', -24, now())
SAMPLE BY 5m
ORDER BY timestamp;
`;

msg.method = "GET";
msg.url = "http://questdb:9000/exec?query=" + encodeURIComponent(query);

return msg;
